          "heading": "Luther: rest is not abandonment",
          "text": "Luther handles the tension between Genesis's divine rest and Christ's statement that the Father still works. In the quoted paragraph, rest means no further design to create another heaven and earth, not cessation of preservation and government. His subsequent language separates creation-work from government-work.[2]",
